#!/usr/bin/env python3
"""Randomised cross-check of plan and replay against an independent reference."""
import hashlib, ipaddress, json, os, random, subprocess, sys

SUB = "/app/submission/ipv6_replay.py"
WORK = "/workspace/scratch/work4"
os.makedirs(WORK, exist_ok=True)
rng = random.Random(20240917)

def A(v): return str(ipaddress.IPv6Address(v))
def can(seed, w, s, net):
    p = ("ipv6-evidence-v1\n%d\n%s\n%s\n%s\n" % (seed, w, s, net)).encode("ascii")
    c0 = int.from_bytes(hashlib.sha256(p).digest()[:8], "big") | (1 << 63)
    return c0, c0 ^ 1

def ref_plan(m):
    wins = sorted(m["windows"], key=lambda w: w["id"])
    probes = []
    for w in wins:
        q = 0
        for s in sorted(w["scopes"], key=lambda s: s["id"]):
            net = ipaddress.IPv6Network(s["prefix"])
            plen = net.prefixlen
            base = int(net.network_address)
            for sub in sorted(s["subnets"]):
                b = base + (sub << 64) if plen == 56 else base
                n64 = A(b) + "/64"
                c0, c1 = can(m["seed"], w["id"], s["id"], n64)
                targs = [("low", i, i) for i in range(1, m["low_count"] + 1)]
                targs += [("canary", 0, c0), ("canary", 1, c1)]
                for role, slot, iid in targs:
                    for att in range(m["attempts"]):
                        probes.append({
                            "id": "%s/%s/%d/%s-%d/%d" % (w["id"], s["id"], sub, role, slot, att),
                            "window": w["id"], "scope": s["id"], "subnet": sub,
                            "target": A(b | iid), "role": role, "slot": slot, "attempt": att,
                            "sent_ms": w["start_ms"] + q * m["spacing_ms"],
                            "deadline_ms": w["start_ms"] + q * m["spacing_ms"] + m["timeout_ms"],
                        })
                        q += 1
    return {"version": 1, "probes": probes}

def ref_replay(m, rows):
    plan = ref_plan(m)
    index = {p["id"]: p for p in plan["probes"]}
    segs = {}
    order = []
    for p in plan["probes"]:
        key = (p["window"], p["scope"], p["subnet"])
        if key not in segs:
            segs[key] = {"internal": set(), "external": set(), "hits": set(), "t": {}}
            order.append(key)
        seg = segs[key]
        if p["role"] == "low":
            seg["t"].setdefault(p["slot"], {"i": set(), "e": set(), "es": set(), "r": set()})
    diags = []
    seen = set()
    acc = dup = 0
    for n, raw in enumerate(rows, 1):
        reason = None
        try:
            obj = json.loads(raw)
            if isinstance(obj, dict) and set(obj) == {"probe_id","received_ms","target","source","type","code"}:
                pass
            else:
                reason = "schema"
        except Exception:
            reason = "json"
        if reason is None:
            pid = obj["probe_id"]; tgt = obj["target"]; src = obj["source"]
            rec = obj["received_ms"]; ty = obj["type"]; co = obj["code"]
            if not isinstance(pid, str) or not isinstance(tgt, str) or not isinstance(src, str):
                reason = "schema"
            elif not pid or len(pid) > 200:
                reason = "schema"
            elif not all(isinstance(x, int) and not isinstance(x, bool) for x in (rec, ty, co)):
                reason = "schema"
        if reason is None:
            try:
                tv = int(ipaddress.IPv6Address(obj["target"]))
                sv = int(ipaddress.IPv6Address(obj["source"]))
                if (tv >> 96) != 0x20010db8 or (sv >> 96) != 0x20010db8:
                    reason = "address"
            except Exception:
                reason = "address"
        if reason is None:
            if obj["probe_id"] not in index:
                reason = "unknown_probe"
        if reason is None:
            if tv != int(ipaddress.IPv6Address(index[obj["probe_id"]]["target"])):
                reason = "target_mismatch"
        if reason is None:
            pr = index[obj["probe_id"]]
            if not (pr["sent_ms"] <= obj["received_ms"] < pr["deadline_ms"]):
                reason = "time"
        if reason is None:
            if not ((obj["type"] == 129 and obj["code"] == 0) or (obj["type"] == 1 and 0 <= obj["code"] <= 6)):
                reason = "icmp"
        if reason is not None:
            diags.append({"line": n, "reason": reason})
            continue
        key = (obj["probe_id"], obj["received_ms"], tv, sv, obj["type"], obj["code"])
        if key in seen:
            dup += 1
            continue
        seen.add(key); acc += 1
        p = index[obj["probe_id"]]
        seg = segs[(p["window"], p["scope"], p["subnet"])]
        if p["role"] == "canary":
            if obj["type"] == 129 and obj["code"] == 0 and sv == tv:
                seg["hits"].add(p["slot"])
        else:
            t = seg["t"][p["slot"]]
            t["r"].add(p["attempt"])
            if obj["type"] == 129 and obj["code"] == 0:
                if sv == tv:
                    t["i"].add(p["attempt"]); seg["internal"].add(tv)
            else:
                if sv != tv:
                    t["e"].add(p["attempt"]); t["es"].add(sv); seg["external"].add(sv)
    out = []
    for key in order:
        w, s, sub = key
        seg = segs[key]
        inter = seg["internal"] & seg["external"]
        state = "alias_suspect" if len(seg["hits"]) == 2 else ("ambiguous" if inter else "usable")
        expo = "excluded" if state != "usable" else ("observed_internal_reply" if seg["internal"] else "inconclusive")
        base = None
        for p in plan["probes"]:
            if (p["window"], p["scope"], p["subnet"]) == key:
                base = int(ipaddress.IPv6Address(p["target"])) & ~((1 << 64) - 1)
                break
        tg = []
        for slot in sorted(seg["t"]):
            t = seg["t"][slot]
            if state == "alias_suspect": cls = "alias_suspect"
            elif state == "ambiguous": cls = "ambiguous"
            else:
                cls = "mixed" if t["i"] and t["e"] else ("internal" if t["i"] else ("external" if t["e"] else "unknown"))
            tg.append({"address": A(base | slot), "classification": cls,
                       "internal_attempts": sorted(t["i"]), "external_attempts": sorted(t["e"]),
                       "external_sources": [A(x) for x in sorted(t["es"])],
                       "silent_attempts": [a for a in range(m["attempts"]) if a not in t["r"]]})
        out.append({"window": w, "scope": s, "subnet": sub, "network": A(base) + "/64",
                    "state": state, "exposure": expo, "canary_hits": sorted(seg["hits"]),
                    "internal": [A(x) for x in sorted(seg["internal"])],
                    "external": [A(x) for x in sorted(seg["external"])],
                    "overlap": [A(x) for x in sorted(inter)], "targets": tg})
    return {"version": 1, "accepted_rows": acc, "duplicate_rows": dup,
            "diagnostics": diags, "segments": out}

def run(cmd, args):
    p = subprocess.run([sys.executable, SUB, cmd] + args, capture_output=True, timeout=300)
    if p.returncode != 0:
        raise SystemExit("rc=%s stderr=%s" % (p.returncode, p.stderr.decode()[:500]))
    return json.loads(p.stdout)

def rand_manifest():
    nwin = rng.randint(0, 3)
    wins = []
    used_ids = set()
    for i in range(nwin):
        wid = "w%d" % rng.randint(0, 50)
        if wid in used_ids: continue
        used_ids.add(wid)
        scopes = []
        sids = set()
        for j in range(rng.randint(0, 3)):
            sid = "s%d" % rng.randint(0, 50)
            if sid in sids: continue
            sids.add(sid)
            if rng.random() < 0.5:
                prefix = "2001:db8:%x:%x00::/56" % (rng.randint(0, 0xffff), rng.randint(0, 0xffff))
                k = rng.randint(1, 4)
                subs = rng.sample(range(256), k)
            else:
                prefix = "2001:db8:%x:%x00::/64" % (rng.randint(0, 0xffff), rng.randint(0, 0xffff))
                subs = [0]
            scopes.append({"id": sid, "prefix": prefix, "subnets": subs})
        wins.append({"id": wid, "start_ms": rng.choice([0, 1000, 10**12]), "scopes": scopes})
    return {"version": 1, "seed": rng.randint(0, 2**64 - 1),
            "low_count": rng.randint(1, 4), "attempts": rng.randint(1, 3),
            "spacing_ms": rng.choice([1, 10, 1000]), "timeout_ms": rng.choice([1, 100, 1000000]),
            "windows": wins}

def rand_rows(man, plan):
    rows = []
    for i in range(rng.randint(0, 40)):
        kind = rng.random()
        if kind < 0.55 and plan["probes"]:
            p = rng.choice(plan["probes"])
            recv = rng.choice([p["sent_ms"], p["sent_ms"] + 1, p["deadline_ms"] - 1,
                               p["deadline_ms"], p["sent_ms"] - 1, 0])
            tgt = p["target"] if rng.random() < 0.9 else A(int(ipaddress.IPv6Address(p["target"])) + 5)
            src = p["target"] if rng.random() < 0.6 else A(0x20010db8 << 96 | rng.randint(1, 100))
            ty, co = rng.choice([(129, 0), (129, 0), (1, 0), (1, 1), (1, 6), (1, 7), (128, 0)])
            rows.append(json.dumps({"probe_id": p["id"], "received_ms": recv, "target": tgt,
                                    "source": src, "type": ty, "code": co}))
        elif kind < 0.65:
            rows.append(json.dumps({"probe_id": "nope", "received_ms": 1, "target": "2001:db8::1",
                                    "source": "2001:db8::1", "type": 129, "code": 0}))
        elif kind < 0.72:
            rows.append("{broken")
        elif kind < 0.78:
            rows.append("")
        elif kind < 0.84:
            rows.append(json.dumps({"probe_id": "x", "received_ms": 1}))
        elif kind < 0.9:
            rows.append(json.dumps({"probe_id": "x" * 250, "received_ms": 1, "target": "2001:db8::1",
                                    "source": "2001:db8::1", "type": 129, "code": 0}))
        else:
            rows.append(json.dumps({"probe_id": "x", "received_ms": 1, "target": "2001:db8::1",
                                    "source": "2001:db8::1", "type": 129, "code": 0, "extra": 1}))
    return rows

fails = 0
for trial in range(120):
    man = rand_manifest()
    # avoid overlapping selections inside a window (invalid by contract)
    ok = True
    for w in man["windows"]:
        bases = []
        for s in w["scopes"]:
            net = ipaddress.IPv6Network(s["prefix"])
            b = int(net.network_address)
            for sub in s["subnets"]:
                x = b + (sub << 64) if net.prefixlen == 56 else b
                if x in bases: ok = False
                bases.append(x)
    if not ok: continue
    mp = os.path.join(WORK, "m.json")
    open(mp, "w").write(json.dumps(man))
    got = run("plan", [mp])
    exp = ref_plan(man)
    if got != exp:
        print("PLAN MISMATCH trial", trial); print(json.dumps(man)); fails += 1
        for a, b in zip(got["probes"], exp["probes"]):
            if a != b:
                print("got", a); print("exp", b); break
        break
    rows = rand_rows(man, got)
    rp = os.path.join(WORK, "r.jsonl")
    open(rp, "w").write("\n".join(rows) + ("\n" if rows else ""))
    gotr = run("replay", [mp, rp])
    expr = ref_replay(man, rows)
    if gotr != expr:
        print("REPLAY MISMATCH trial", trial); print(json.dumps(man)); print(rows)
        for k in ("accepted_rows","duplicate_rows","diagnostics"):
            if gotr[k] != expr[k]: print("  ", k, "got", gotr[k], "exp", expr[k])
        if gotr["segments"] != expr["segments"]:
            for a, b in zip(gotr["segments"], expr["segments"]):
                if a != b:
                    print("  seg got", json.dumps(a)); print("  seg exp", json.dumps(b)); break
        fails += 1
        break
print("random failures:", fails)
PYEOF
cd /workspace/scratch && python3 t_random.py
